+import 'package:shared_preferences/shared_preferences.dart';
+
+class CurrentUser {
+  static final CurrentUser _instance = CurrentUser._internal();
+  factory CurrentUser() => _instance;
+
+  CurrentUser._internal();
+
+  String? token;
+  int? ortuId;
+  String? nama;
+  String? email;
+
+  void setUserData({
+    required String token,
+    required int ortuId,
+    required String nama,
+    required String email,
+  }) {
+    this.token = token;
+    this.ortuId = ortuId;
+    this.nama = nama;
+    this.email = email;
+
+    _saveToPrefs(); // Simpan otomatis ke SharedPreferences
+  }
+
+  void clear() {
+    token = null;
+    ortuId = null;
+    nama = null;
+    email = null;
+    _clearPrefs(); // Hapus data di SharedPreferences
+  }
+
+  Future<void> _saveToPrefs() async {
+    final prefs = await SharedPreferences.getInstance();
+    if (token != null) prefs.setString('token', token!);
+    if (ortuId != null) prefs.setInt('ortu_id', ortuId!);
+    if (nama != null) prefs.setString('nama', nama!);
+    if (email != null) prefs.setString('email', email!);
+  }
+
+  Future<void> _clearPrefs() async {
+    final prefs = await SharedPreferences.getInstance();
+    await prefs.remove('token');
+    await prefs.remove('ortu_id');
+    await prefs.remove('nama');
+    await prefs.remove('email');
+  }
+
+  Future<void> loadUserData() async {
+    final prefs = await SharedPreferences.getInstance();
+    token = prefs.getString('token');
+
+    // Handle kemungkinan ortu_id disimpan sebagai String
+    final ortuIdRaw = prefs.get('ortu_id');
+    if (ortuIdRaw is int) {
+      ortuId = ortuIdRaw;
+    } else if (ortuIdRaw is String) {
+      ortuId = int.tryParse(ortuIdRaw);
+    } else {
+      ortuId = null;
+    }
+
+    nama = prefs.getString('nama');
+    email = prefs.getString('email');
+  }
+}

